import org.apache.shardingsphere.sql.parser.autogen.SQLServerStatementLexer;
import org.apache.shardingsphere.sql.parser.autogen.SQLServerStatementParser;

public class ParseTest {
    static class ThrowingListener extends BaseErrorListener {
        @Override
        public void syntaxError(Recognizer<?, ?> r, Object sym, int line, int pos, String msg, RecognitionException e) {
            throw new RuntimeException("line " + line + ":" + pos + " " + msg);
        }
    }

    static void parse(String sql) {
        try {
            SQLServerStatementLexer lexer = new SQLServerStatementLexer(CharStreams.fromString(sql));
            lexer.removeErrorListeners();
            lexer.addErrorListener(new ThrowingListener());
            SQLServerStatementParser parser = new SQLServerStatementParser(new CommonTokenStream(lexer));
            parser.removeErrorListeners();
            parser.addErrorListener(new ThrowingListener());
            parser.execute();
            System.out.println("OK   : " + sql);
        } catch (RuntimeException ex) {
            System.out.println("FAIL : " + sql + "\n        -> " + ex.getMessage());
        }
    }

    public static void main(String[] args) {
        parse("INSERT INTO t_order WITH (TABLOCK) SELECT * FROM t_source");
        parse("INSERT INTO t_order WITH (TABLOCK, HOLDLOCK) (order_id, user_id) SELECT order_id, user_id FROM t_source");
        parse("INSERT INTO t_order EXEC proc_name @param1 = 1, @param2 = 'x'");
        parse("INSERT INTO t_order EXEC dbo.proc_name @p = 10");
        parse("SELECT CAST(SYSTEM_USER AS VARCHAR) + '-' + CAST(DB_NAME() AS VARCHAR) AS info FROM t_order");
        parse("SELECT o.order_id, u.user_name, COUNT(*) AS cnt FROM t_order o JOIN t_user u ON o.user_id = u.user_id "
                + "WHERE u.user_name LIKE '%a%' AND o.status LIKE 'A%' GROUP BY o.order_id, u.user_name HAVING COUNT(*) > 1 ORDER BY cnt DESC");
    }
}
